package me.minis.ledger;

import android.content.ContentValues;
import android.database.Cursor;
import android.database.DatabaseUtils;
import android.database.sqlite.SQLiteDatabase;
import org.json.*;
import java.util.*;

/** Financial relationships share stable IDs, entry references and the existing undo transaction. */
final class FinanceData {
 static final long MAX=99999999999L;
 static final Set<String> TYPES=new HashSet<>(Arrays.asList("split","refund","case","settlement","tag","taglink","goal","allocation","rule","layout","source","evidence","merge","distinct","batch","statement"));
 static void install(SQLiteDatabase db){
  db.execSQL("CREATE TABLE IF NOT EXISTS finance(id TEXT PRIMARY KEY,type TEXT NOT NULL,entry INTEGER NOT NULL DEFAULT 0,peer INTEGER NOT NULL DEFAULT 0,cents INTEGER NOT NULL DEFAULT 0,category TEXT NOT NULL DEFAULT '',label TEXT NOT NULL DEFAULT '',data TEXT NOT NULL DEFAULT '{}',rev INTEGER NOT NULL DEFAULT 1)");
  db.execSQL("CREATE INDEX IF NOT EXISTS finance_entry ON finance(entry,type)");
  db.execSQL("CREATE INDEX IF NOT EXISTS finance_peer ON finance(peer,type)");
  db.execSQL("CREATE INDEX IF NOT EXISTS finance_kind ON finance(type,category)");
  db.execSQL("CREATE UNIQUE INDEX IF NOT EXISTS finance_source ON finance(category,label) WHERE type='source' AND label<>''");
  for(String side:new String[]{"before","after"}){db.execSQL("CREATE TABLE IF NOT EXISTS finance_"+side+" AS SELECT f.*,CAST(0 AS INTEGER) AS op FROM finance f WHERE 0");db.execSQL("CREATE UNIQUE INDEX IF NOT EXISTS finance_"+side+"_key ON finance_"+side+"(op,id)");}
  db.execSQL("CREATE TRIGGER IF NOT EXISTS finance_bu BEFORE UPDATE ON finance WHEN (SELECT id FROM edit_context)>0 BEGIN INSERT OR IGNORE INTO finance_before SELECT f.*,(SELECT id FROM edit_context) FROM finance f WHERE f.id=old.id AND NOT EXISTS(SELECT 1 FROM finance_after WHERE id=old.id AND op=(SELECT id FROM edit_context)); END");
  db.execSQL("CREATE TRIGGER IF NOT EXISTS finance_bd BEFORE DELETE ON finance WHEN (SELECT id FROM edit_context)>0 BEGIN INSERT OR IGNORE INTO finance_before SELECT f.*,(SELECT id FROM edit_context) FROM finance f WHERE f.id=old.id AND NOT EXISTS(SELECT 1 FROM finance_after WHERE id=old.id AND op=(SELECT id FROM edit_context)); INSERT OR REPLACE INTO finance_after VALUES(old.id,'deleted',0,0,0,'','','{}',0,(SELECT id FROM edit_context)); END");
  for(String event:new String[]{"INSERT","UPDATE"})db.execSQL("CREATE TRIGGER IF NOT EXISTS finance_a"+event.charAt(0)+" AFTER "+event+" ON finance BEGIN INSERT INTO ui_changes(id,os,ns) VALUES(0,'reset','reset'); INSERT OR REPLACE INTO finance_after SELECT new.id,new.type,new.entry,new.peer,new.cents,new.category,new.label,new.data,new.rev,(SELECT id FROM edit_context) WHERE (SELECT id FROM edit_context)>0; END");
  db.execSQL("CREATE TRIGGER IF NOT EXISTS finance_ad AFTER DELETE ON finance BEGIN INSERT INTO ui_changes(id,os,ns) VALUES(0,'reset','reset'); END");
  db.execSQL("CREATE TRIGGER IF NOT EXISTS finance_protect_delete BEFORE DELETE ON entries WHEN EXISTS(SELECT 1 FROM finance WHERE entry=old._id OR peer=old._id) BEGIN SELECT RAISE(ABORT,'请先解除此账单的关联关系'); END");
  db.execSQL("CREATE TRIGGER IF NOT EXISTS finance_protect_update BEFORE UPDATE OF kind,status,cents ON entries WHEN (new.kind<>old.kind OR new.status<>old.status OR new.cents<>old.cents) AND EXISTS(SELECT 1 FROM finance WHERE type IN ('split','refund','case','settlement','allocation') AND (entry=old._id OR peer=old._id)) BEGIN SELECT RAISE(ABORT,'此账单已有金额关系，请先解除或调整关联再修改金额、方向或状态'); END");
  for(String event:new String[]{"INSERT","UPDATE","DELETE"}){String ref=event.equals("DELETE")?"old":"new";db.execSQL("CREATE TRIGGER IF NOT EXISTS finance_version_"+event+" AFTER "+event+" ON finance BEGIN UPDATE ui_version SET rev=rev+1 WHERE id IN ("+ref+".entry,"+ref+".peer); END");}
  db.execSQL("CREATE VIEW IF NOT EXISTS ledger_parts AS SELECT e.*,e.category AS part_category,e.cents-COALESCE((SELECT sum(f.cents) FROM finance f WHERE f.type='refund' AND f.entry=e._id),0) AS part_cents,'' AS part_id FROM entries e WHERE NOT EXISTS(SELECT 1 FROM finance f WHERE f.type='split' AND f.entry=e._id) UNION ALL SELECT e.*,f.category,f.cents,f.id FROM entries e JOIN finance f ON f.entry=e._id AND f.type='split' UNION ALL SELECT e.*,f.category,f.cents,f.id FROM entries e JOIN finance f ON f.entry=e._id AND f.type='refund'");
 }
 static JSONArray query(SQLiteDatabase db,String sql,String...args)throws JSONException{JSONArray a=new JSONArray();try(Cursor c=db.rawQuery(sql,args)){while(c.moveToNext())a.put(UndoLog.row(c));}return a;}
 static long number(SQLiteDatabase db,String sql,String...args){return DatabaseUtils.longForQuery(db,sql,args);}
 static JSONObject get(SQLiteDatabase db,String id)throws JSONException{JSONArray a=query(db,"SELECT * FROM finance WHERE id=?",id);return a.length()==0?null:a.getJSONObject(0);}
 static JSONObject entry(SQLiteDatabase db,long id)throws JSONException{JSONArray a=query(db,"SELECT e.*,COALESCE(v.rev,0) AS rev FROM entries e LEFT JOIN ui_version v ON v.id=e._id WHERE e._id=?",""+id);if(a.length()==0)throw new IllegalArgumentException("账单不存在");return a.getJSONObject(0);}
 static JSONObject object(String type,long entry,long peer,long cents,String category,String label,JSONObject data)throws JSONException{return new JSONObject().put("id",UUID.randomUUID().toString()).put("type",type).put("entry",entry).put("peer",peer).put("cents",cents).put("category",category).put("label",label).put("data",data.toString()).put("rev",1);}
 static void put(SQLiteDatabase db,JSONObject o)throws JSONException{
  if(!TYPES.contains(o.getString("type"))||o.getString("id").length()>100||o.getString("label").length()>(o.getString("type").equals("statement")?2000:200)||o.getString("category").length()>255||o.getString("data").length()>16000||o.getLong("cents")<0||o.getLong("cents")>MAX)throw new IllegalArgumentException("关系数据不合法");new JSONObject(o.getString("data"));
  ContentValues v=new ContentValues();for(String k:new String[]{"id","type","category","label","data"})v.put(k,o.getString(k));for(String k:new String[]{"entry","peer","cents","rev"})v.put(k,o.getLong(k));
  if(db.update("finance",v,"id=?",new String[]{o.getString("id")})==0)db.insertOrThrow("finance",null,v);
 }
 static void checkRevision(JSONObject e,JSONObject p)throws JSONException{if(p.has("rev")&&e.getLong("rev")!=p.getLong("rev"))throw new IllegalStateException("记录已变化，请重新打开后操作");}
 static void money(long cents){if(cents<=0||cents>MAX)throw new IllegalArgumentException("金额须大于0，最多999999999.99元");}
 static void category(String c){if(!Arrays.asList(LedgerDb.CATEGORIES).contains(c))throw new IllegalArgumentException("分类不合法");}
 static void confirmed(JSONObject e,String kind)throws JSONException{if(!e.getString("status").equals("confirmed")||(!kind.isEmpty()&&!e.getString("kind").equals(kind)))throw new IllegalArgumentException("请选择已确认的"+(kind.equals("expense")?"支出":kind.equals("refund")?"退款":kind.equals("income")?"收入":"账单"));}
 static void requireUnlinked(SQLiteDatabase db,long id)throws JSONException{if(number(db,"SELECT count(*) FROM finance WHERE type IN ('split','refund','case','settlement','allocation') AND (entry=? OR peer=?)",""+id,""+id)>0)throw new IllegalArgumentException("此账单已有拆分、退款、结算或目标关联，请先解除关系再忽略");}
 static long sum(SQLiteDatabase db,String where,String...args){return number(db,"SELECT COALESCE(sum(cents),0) FROM finance WHERE "+where,args);}
 static void validateEntry(SQLiteDatabase db,long id)throws JSONException{
  JSONObject e=entry(db,id);long amount=e.getLong("cents");String kind=e.getString("kind");
  JSONArray rel=query(db,"SELECT * FROM finance WHERE entry=? OR peer=?",""+id,""+id);boolean needsConfirmed=false;
  for(int i=0;i<rel.length();i++){JSONObject f=rel.getJSONObject(i);String type=f.getString("type");if(Arrays.asList("split","refund","case","settlement").contains(type))needsConfirmed=true;
   if(f.getLong("entry")==id){if(type.equals("split")||type.equals("case")&&!f.getString("category").equals("loanIn")){if(!kind.equals("expense"))throw new IllegalArgumentException("此记录已有消费或借出关系，不能修改收支方向");}if(type.equals("refund")&&!kind.equals("refund"))throw new IllegalArgumentException("退款关联要求退款流水");if(type.equals("case")&&f.getString("category").equals("loanIn")&&!kind.equals("income"))throw new IllegalArgumentException("借入本金要求收入流水");if(type.equals("settlement")&&!kind.equals(f.getString("category").equals("loanIn")?"expense":"income"))throw new IllegalArgumentException("归还方向不符");}
  }
  if(needsConfirmed&&!e.getString("status").equals("confirmed"))throw new IllegalArgumentException("请先解除拆分、退款或结算关系，再忽略该记录");
  long split=sum(db,"type='split' AND entry=?",""+id);if(split>0&&split!=amount)throw new IllegalArgumentException("拆分合计必须等于账单金额，请先调整或取消拆分");
  if(sum(db,"type IN ('refund','settlement','allocation') AND entry=?",""+id)>amount)throw new IllegalArgumentException("同一笔资金的累计分配超出实际金额");
  long refunded=sum(db,"type='refund' AND peer=?",""+id);if(refunded>amount)throw new IllegalArgumentException("退款超过原消费可退金额");
  JSONArray cases=query(db,"SELECT * FROM finance WHERE type='case' AND entry=?",""+id);if(cases.length()>1)throw new IllegalArgumentException("同一账单不能同时标为借款和代垫");
  if(cases.length()>0){JSONObject c=cases.getJSONObject(0);if(c.getLong("cents")>amount-refunded||sum(db,"type='settlement' AND peer=?",""+id)>c.getLong("cents"))throw new IllegalArgumentException("应收/本金、退款与已结算金额冲突，请先调整关系");if(sum(db,"type IN ('settlement','allocation') AND entry=?",""+id)>0)throw new IllegalArgumentException("同一资金不能同时作为本金和回款/目标分配");}
  JSONArray splits=query(db,"SELECT * FROM finance WHERE type='split' AND entry=?",""+id);for(int i=0;i<splits.length();i++){JSONObject s=splits.getJSONObject(i);long allocated=0;JSONArray refs=query(db,"SELECT data,cents FROM finance WHERE type='refund' AND peer=?",""+id);for(int j=0;j<refs.length();j++)if(new JSONObject(refs.getJSONObject(j).getString("data")).optString("split").equals(s.getString("id")))allocated+=refs.getJSONObject(j).getLong("cents");if(allocated>s.getLong("cents"))throw new IllegalArgumentException("退款超出拆分项金额");}
 }
 static void validateAll(SQLiteDatabase db)throws JSONException{
  if(number(db,"SELECT count(*) FROM finance f WHERE (entry>0 AND NOT EXISTS(SELECT 1 FROM entries WHERE _id=f.entry)) OR (peer>0 AND NOT EXISTS(SELECT 1 FROM entries WHERE _id=f.peer))")>0)throw new IllegalArgumentException("存在无效的账单引用");
  try(Cursor c=db.rawQuery("SELECT entry FROM finance WHERE entry>0 UNION SELECT peer FROM finance WHERE peer>0",null)){while(c.moveToNext())validateEntry(db,c.getLong(0));}
  if(number(db,"SELECT count(*) FROM finance WHERE type IN ('split','refund','case','settlement','goal','allocation') AND cents<=0")>0)throw new IllegalArgumentException("财务关系金额必须大于0");
  JSONArray refs=query(db,"SELECT * FROM finance WHERE type IN ('taglink','allocation','refund','settlement')");for(int i=0;i<refs.length();i++){JSONObject f=refs.getJSONObject(i),d=new JSONObject(f.getString("data"));String t=f.getString("type");if(t.equals("taglink")||t.equals("allocation")){JSONObject target=get(db,d.getString(t.equals("taglink")?"tag":"goal"));if(target==null||!target.getString("type").equals(t.equals("taglink")?"tag":"goal"))throw new IllegalArgumentException("标签或目标引用不存在");}if(t.equals("refund")){confirmed(entry(db,f.getLong("peer")),"expense");String sid=d.optString("split");if(!sid.isEmpty()){JSONObject split=get(db,sid);if(split==null||!split.getString("type").equals("split")||split.getLong("entry")!=f.getLong("peer")||!split.getString("category").equals(f.getString("category")))throw new IllegalArgumentException("退款拆分项无效");}else if(number(db,"SELECT count(*) FROM finance WHERE type='split' AND entry=?",""+f.getLong("peer"))>0)throw new IllegalArgumentException("已拆分消费需要指定退款项目");}if(t.equals("settlement")&&number(db,"SELECT count(*) FROM finance WHERE type='case' AND entry=? AND category=?",""+f.getLong("peer"),f.getString("category"))!=1)throw new IllegalArgumentException("结算案件不存在");}
 }
 static long canonical(SQLiteDatabase db,long id){
  Set<Long> seen=new HashSet<>();while(seen.add(id)){try(Cursor c=db.rawQuery("SELECT peer FROM finance WHERE type='merge' AND entry=?",new String[]{""+id})){if(!c.moveToFirst())return id;id=c.getLong(0);}}throw new IllegalStateException("合并引用存在循环");
 }
 static JSONObject detail(SQLiteDatabase db,long id)throws JSONException{
  id=canonical(db,id);JSONObject e=entry(db,id);JSONArray objects=query(db,"SELECT * FROM finance WHERE entry=? OR peer=? ORDER BY type,id",""+id,""+id);
  long refund=sum(db,"type='refund' AND peer=?",""+id),settled=sum(db,"type='settlement' AND peer=?",""+id),receivable=sum(db,"type='case' AND entry=? AND category='reimbursement'",""+id);
  JSONObject result=new JSONObject().put("entry",e).put("objects",objects).put("refunded",refund).put("paid",e.getLong("cents")-refund).put("settled",settled).put("receivable",Math.max(0,receivable-settled)).put("personal",e.getLong("cents")-refund-sum(db,"type='settlement' AND category='reimbursement' AND peer=?",""+id)-sum(db,"type='case' AND category IN ('loanOut','loanIn') AND entry=?",""+id));
  result.put("explanation",e.optString("semantic").equals("user-edited")?"此记录已由你手工修改；以下为原始采集依据，不代表当前最终字段。":e.optString("source").equals("manual")?"此记录由手动记账创建。":"未保存字段级提取依据的老记录不作追溯推断。");return result;
 }
 static Object mutate(SQLiteDatabase db,String op,JSONObject p)throws Exception{
  if(op.equals("remove")){JSONObject old=get(db,p.getString("id"));if(old==null)throw new IllegalArgumentException("记录已不存在");checkRevision(old,p);String t=old.getString("type");if(Arrays.asList("source","evidence","merge","distinct","batch","statement").contains(t))throw new IllegalArgumentException("请通过撤销处理此操作");if(t.equals("tag")){JSONArray links=query(db,"SELECT id,data FROM finance WHERE type='taglink'");for(int i=0;i<links.length();i++)if(new JSONObject(links.getJSONObject(i).getString("data")).optString("tag").equals(old.getString("id")))db.delete("finance","id=?",new String[]{links.getJSONObject(i).getString("id")});}db.delete("finance","id=?",new String[]{old.getString("id")});validateAll(db);return true;}
  if(op.equals("split")){long id=p.getLong("entry");JSONObject e=entry(db,id);checkRevision(e,p);confirmed(e,"expense");JSONArray rows=p.getJSONArray("rows");if(rows.length()>100)throw new IllegalArgumentException("最多100个拆分项");if(sum(db,"type='refund' AND peer=?",""+id)>0)throw new IllegalArgumentException("请先解除已分配退款，再调整拆分");db.delete("finance","type='split' AND entry=?",new String[]{""+id});long total=0;for(int i=0;i<rows.length();i++){JSONObject r=rows.getJSONObject(i);long n=r.getLong("cents");money(n);category(r.getString("category"));total=Math.addExact(total,n);put(db,object("split",id,0,n,r.getString("category"),r.optString("note"),new JSONObject()));}if(rows.length()>0&&total!=e.getLong("cents"))throw new IllegalArgumentException("拆分之和必须等于原金额");validateAll(db);return true;}
  if(op.equals("refund")){long id=p.getLong("entry"),peer=p.getLong("peer"),n=p.getLong("cents");money(n);JSONObject refund=entry(db,id),expense=entry(db,peer);checkRevision(refund,p);confirmed(refund,"refund");confirmed(expense,"expense");String sid=p.optString("split"),cat=expense.getString("category");if(!sid.isEmpty()){JSONObject split=get(db,sid);if(split==null||!split.getString("type").equals("split")||split.getLong("entry")!=peer)throw new IllegalArgumentException("拆分项不存在");cat=split.getString("category");}put(db,object("refund",id,peer,n,cat,"",new JSONObject().put("split",sid)));validateAll(db);return true;}
  if(op.equals("case")){long id=p.getLong("entry"),n=p.getLong("cents");String kind=p.getString("kind");if(!Arrays.asList("reimbursement","loanOut","loanIn").contains(kind))throw new IllegalArgumentException("案件类型错误");money(n);JSONObject e=entry(db,id);checkRevision(e,p);confirmed(e,kind.equals("loanIn")?"income":"expense");if(p.getString("name").trim().isEmpty())throw new IllegalArgumentException("请填写对方称呼");JSONArray existing=query(db,"SELECT * FROM finance WHERE type='case' AND entry=?",""+id);JSONObject o=object("case",id,0,n,kind,p.getString("name"),new JSONObject().put("due",p.optLong("due")).put("budgetExclude",p.optBoolean("budgetExclude")));if(existing.length()>0){JSONObject old=existing.getJSONObject(0);if(p.has("caseRev")&&old.getLong("rev")!=p.getLong("caseRev"))throw new IllegalStateException("案件已变化，请重新打开");o.put("id",old.getString("id")).put("rev",old.getLong("rev")+1);}put(db,o);validateAll(db);return o;}
  if(op.equals("settle")){JSONObject c=get(db,p.getString("case"));if(c==null||!c.getString("type").equals("case"))throw new IllegalArgumentException("案件不存在");if(p.has("caseRev")&&c.getLong("rev")!=p.getLong("caseRev"))throw new IllegalStateException("案件已变化，请重新打开");long id=p.getLong("entry"),n=p.getLong("cents");money(n);JSONObject e=entry(db,id);checkRevision(e,p);confirmed(e,c.getString("category").equals("loanIn")?"expense":"income");put(db,object("settlement",id,c.getLong("entry"),n,c.getString("category"),c.getString("label"),new JSONObject()));validateAll(db);return true;}
  if(op.equals("tag")||op.equals("goal")||op.equals("layout")){
   String name=p.optString("name").trim();if(!op.equals("layout")&&(name.isEmpty()||name.length()>60))throw new IllegalArgumentException("名称须为1至60字");long n=op.equals("goal")?p.getLong("cents"):0;if(op.equals("goal"))money(n);
   JSONObject data=new JSONObject();if(op.equals("goal"))data.put("due",p.optLong("due")).put("archived",p.optBoolean("archived")).put("completed",p.optBoolean("completed")).put("mode","plan");if(op.equals("layout")){JSONArray order=p.getJSONArray("order"),hidden=p.getJSONArray("hidden");Set<String> valid=new HashSet<>(Arrays.asList("quick","period","summary","pending","tools","calendar","projects","goals")),seen=new HashSet<>();for(int i=0;i<order.length();i++)if(!valid.contains(order.getString(i))||!seen.add(order.getString(i)))throw new IllegalArgumentException("布局模块不合法");for(int i=0;i<hidden.length();i++)if(!valid.contains(hidden.getString(i)))throw new IllegalArgumentException("隐藏模块不合法");data.put("order",order).put("hidden",hidden);}
   JSONObject o=object(op,0,0,n,"",name,data);String id=op.equals("layout")?"home-layout":p.optString("id");if(!id.isEmpty()){JSONObject old=get(db,id);if(old!=null){checkRevision(old,p);if(!old.getString("type").equals(op))throw new IllegalArgumentException("类型不符");o.put("rev",old.getLong("rev")+1);}o.put("id",id);}put(db,o);return o;
  }
  if(op.equals("taglink")){JSONObject tag=get(db,p.getString("tag"));if(tag==null||!tag.getString("type").equals("tag"))throw new IllegalArgumentException("标签不存在");JSONArray ids=p.getJSONArray("entries");for(int i=0;i<ids.length();i++){long id=ids.getLong(i);confirmed(entry(db,id),"");String objectId="tag:"+tag.getString("id")+":"+id;if(number(db,"SELECT count(*) FROM finance WHERE type='taglink' AND category=? AND entry=?",tag.getString("id"),""+id)==0){JSONObject o=object("taglink",id,0,0,tag.getString("id"),"",new JSONObject().put("tag",tag.getString("id")));o.put("id",objectId);put(db,o);}}return ids.length();}
  if(op.equals("allocation")){JSONObject goal=get(db,p.getString("goal"));if(goal==null||!goal.getString("type").equals("goal"))throw new IllegalArgumentException("目标不存在");long n=p.getLong("cents"),id=p.optLong("entry");money(n);if(id>0)confirmed(entry(db,id),"income");put(db,object("allocation",id,0,n,goal.getString("id"),p.optString("note"),new JSONObject().put("goal",goal.getString("id"))));validateAll(db);return true;}
  throw new IllegalArgumentException("不支持的财务操作");
 }
}
